def apply_sym(S,g):  # S: 0..7, symmetries of square 3x3
    g=[row[:] for row in g]
    for _ in range(S//2 if S<4 else 0): pass
    # build via rot/flip helpers
    def rotm(g): return [list(row) for row in zip(*g[::-1])]
    def flrm(g): return [row[::-1] for row in g]
    outs={}
    x=g
    for k in range(4):
        outs[k]=x; outs[k+4]=flrm(x)
        x=rotm(x)
    return outs[S]
