    for r, c in cells:
        out[r + dr][c + dc] = color

def hmirror(grid):
    """The grid mirrored left to right."""
    return [row[::-1] for row in grid]

def vflip(grid):
    """The grid flipped top to bottom."""
    return grid[::-1]

def hstack(a, b):
